<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#101d2e"><title>The Sentence Observatory</title>
<style>
/* Offline-friendly type stacks. */
:root{--night:#101d2e;--deep:#182b40;--paper:#f3e9d3;--ink:#252b30;--gold:#edb45d;--muted:#a4afbd;--line:#46576a}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--night);color:var(--paper);font:16px/1.7 Georgia,serif;background-image:radial-gradient(#e9d2a325 1px,transparent 1px);background-size:31px 31px}button,textarea{font:inherit}a{color:var(--gold)}button{cursor:pointer}button:focus-visible,a:focus-visible,textarea:focus-visible{outline:3px solid var(--gold);outline-offset:3px}.shell{width:min(1080px,calc(100% - 34px));margin:auto}.mast{display:flex;justify-content:space-between;gap:20px;align-items:center;padding:19px 0;border-bottom:1px solid var(--line);font:11px/1.4 'Courier New',monospace;letter-spacing:.12em;text-transform:uppercase}.mast a{color:var(--paper);text-decoration:none}.mast span{color:var(--muted)}.hero{position:relative;min-height:490px;display:flex;align-items:flex-end;overflow:hidden;margin-top:22px;background:#263847;border:1px solid #b98b5570}.hero img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;object-position:center 55%}.hero:after{content:'';position:absolute;inset:0;background:linear-gradient(90deg,#0d1b2eea 0%,#0d1b2e88 45%,transparent 85%),linear-gradient(0deg,#101d2ec2,transparent 55%)}.hero-copy{position:relative;z-index:1;padding:clamp(26px,6vw,65px);width:min(700px,100%)}.eyebrow,.small{font:11px/1.5 'Courier New',monospace;letter-spacing:.16em;text-transform:uppercase;color:var(--gold)}h1{font-size:clamp(42px,7.7vw,87px);line-height:1.08;letter-spacing:-.065em;margin:14px 0 16px;font-weight:400;text-wrap:balance}h1 i{color:var(--gold)}.hero p{max-width:460px;margin:0;color:#e6e3dc;font-size:14px;line-height:1.85}.hero .artcredit{margin-top:24px;font:10px 'Courier New',monospace;color:#c3c4c0}.intro{display:grid;grid-template-columns:1fr 2fr;gap:40px;padding:54px 0 36px;border-bottom:1px solid var(--line)}.intro p{margin:0;font-size:17px;line-height:1.9}.intro strong{color:var(--gold)}.observatory{padding:38px 0 80px}.progress{display:flex;align-items:center;gap:14px;margin-bottom:18px;font:11px 'Courier New',monospace;letter-spacing:.09em}.track{height:3px;flex:1;background:var(--line)}.fill{height:100%;width:0;background:var(--gold);transition:width .4s}.desk{display:grid;grid-template-columns:minmax(0,1.2fr) minmax(300px,.8fr);background:var(--paper);color:var(--ink);box-shadow:15px 16px 0 #07111f;border:1px solid #dcad67;min-height:390px}.reading{padding:clamp(24px,4vw,48px);border-right:1px solid #d4c7ac}.desk .small{color:#906027}.reading h2{font-size:clamp(25px,3.2vw,42px);line-height:1.25;font-weight:400;margin:22px 0}.reading .text{font-size:clamp(18px,2.3vw,26px);line-height:1.75;border-left:3px solid #cc8e47;padding-left:23px;margin:26px 0;color:#293e4a}.reading .question{font:12px/1.7 'Courier New',monospace;letter-spacing:.02em;color:#52606a}.answers{padding:clamp(24px,4vw,40px);background:#e7dcc3;display:flex;flex-direction:column;gap:12px}.answers .small{margin-bottom:5px}.option{background:#f9f3e5;border:1px solid #b2a589;text-align:left;padding:16px 18px;color:#252b30;line-height:1.5;font-size:14px;transition:transform .15s,background .15s,border-color .15s}.option:hover:not(:disabled){transform:translateX(4px);border-color:#bd7735}.option:disabled{cursor:default}.option.correct{background:#d6e3ca;border-color:#367052}.option.wrong{background:#f3d8cb;border-color:#b8594e}.feedback{min-height:46px;font:12px/1.6 'Courier New',monospace;color:#344c40}.next,.action{border:0;background:var(--night);color:var(--paper);padding:13px 18px;font:12px 'Courier New',monospace;letter-spacing:.04em;align-self:flex-start}.next:hover,.action:hover{background:#31506a}.next[hidden]{display:none}.hint{border:0;background:none;color:#7d4c28;font:11px 'Courier New',monospace;text-align:left;text-decoration:underline;align-self:flex-start;padding:5px 0}.hintText{font-size:12px;line-height:1.65;color:#675b48;min-height:18px}.reward{display:flex;gap:9px;margin-top:35px;align-items:center;font:11px 'Courier New',monospace;color:var(--muted)}.stars{display:flex;gap:9px}.star{width:19px;height:19px;border:1px solid #727e88;border-radius:50%;display:inline-block;transition:background .4s,box-shadow .4s}.star.lit{background:var(--gold);box-shadow:0 0 16px #edb45d99;border-color:var(--gold)}.lab{padding:68px 0 90px;border-top:1px solid var(--line);display:grid;grid-template-columns:1fr 1.2fr;gap:55px}.lab h2{font-size:clamp(29px,4vw,48px);font-weight:400;line-height:1.2;margin:10px 0 20px}.lab p{font-size:14px;color:#c4c6c7;line-height:1.9}.lab .work{background:#223449;border:1px solid #586a76;padding:27px;box-shadow:8px 8px 0 #091522}.lab label{font:11px 'Courier New',monospace;display:block;color:var(--gold);margin:18px 0 8px}.lab textarea{display:block;width:100%;min-height:88px;resize:vertical;padding:14px;color:var(--paper);background:#0e1c2c;border:1px solid #657583;line-height:1.6}.lab .note{font:11px/1.65 'Courier New',monospace;color:var(--muted);margin:12px 0}.pieces{display:flex;flex-wrap:wrap;gap:8px;margin:14px 0}.piece{padding:8px 10px;border:1px solid #b68a56;color:var(--paper);background:#32475c;font:12px/1.5 Georgia,serif}.action{background:var(--gold);color:#1a2532;margin-top:17px}.action:hover{background:#ffd18d}.status{font:11px 'Courier New',monospace;min-height:20px;color:var(--gold)}footer{padding:20px 0 55px;border-top:1px solid var(--line);font:11px/1.9 'Courier New',monospace;color:var(--muted)}@media(max-width:720px){.hero{min-height:440px}.hero:after{background:linear-gradient(0deg,#101d2eee,#101d2e90 62%,transparent)}.intro,.desk,.lab{grid-template-columns:1fr}.intro{gap:15px;padding:38px 0}.reading{border-right:0;border-bottom:1px solid #d4c7ac}.answers{min-height:290px}.lab{gap:18px}.mast span{display:none}}@media(prefers-reduced-motion:reduce){*,*:before,*:after{transition:none!important;scroll-behavior:auto!important}}
</style></head><body><main class="shell"><nav class="mast"><a href="./">← Chloe Reads Jon</a><span>Field guide / difficult reading / № 01</span><a href="#workbench">Your own sentence ↓</a></nav><section class="hero"><img src="sentence-observatory.webp" alt="An illuminated orbit of ideas above an antique scholar’s desk" loading="eager"><div class="hero-copy"><div class="eyebrow">A reading experiment · 4 small discoveries</div><h1>The Sentence <i>Observatory</i></h1><p>For the sentence that makes you read it three times and still say, “Wait, what?” Don’t wrestle the whole thing. Find one orbit at a time.</p><div class="artcredit">Original observatory illustration · generated for this experiment</div></div></section><section class="intro"><div class="eyebrow">A note from the margin</div><p>Jon found a passage in Ratzinger’s <em>Introduction to Christianity</em> genuinely impenetrable. <strong>Fair.</strong> This little observatory is a game about following its four intertwined ideas, not a claim to settle the theology.</p></section><section class="observatory" aria-label="Reading game"><div class="progress"><span id="counter">ORBIT 01 / 04</span><div class="track" role="progressbar" aria-label="Completed reading orbits" aria-valuemin="0" aria-valuemax="4" aria-valuenow="0" id="progress"><div class="fill" id="fill"></div></div><span id="score">0 FOUND</span></div><div class="desk"><article class="reading"><div class="small" id="label">01 / FIRST ORBIT</div><h2 id="heading">Begin with an ordinary verb.</h2><p class="text" id="phrase"></p><p class="question" id="question"></p></article><div class="answers"><div class="small">Choose the clearest reading</div><div id="choices"></div><button class="hint" id="hint" type="button">Open a hint ↗</button><div class="hintText" id="hintText"></div><div class="feedback" id="feedback" aria-live="polite"></div><button class="next" id="next" type="button" hidden>Next orbit →</button></div></div><div class="reward"><div class="stars" id="stars" aria-label="Four reading orbits"></div><span>Each answer lights one part of the observatory.</span></div></section><section class="lab" id="workbench"><div><div class="eyebrow">Your turn / no grades</div><h2>A sentence of your own.</h2><p>Paste or type one knotty sentence. Break it into pieces, then explain it to a tired friend in your own words. Nothing goes to a server; only your browser can remember your note.</p><p>Tip: the machine splits at commas, semicolons, colons, and dashes. Those are starting points, not answers. The real thinking is yours.</p></div><div class="work"><label for="original">01 / THE KNOT</label><textarea id="original" placeholder="Paste one baffling sentence here…"></textarea><button type="button" class="action" id="split">Show the pieces →</button><div class="pieces" id="pieces" aria-live="polite"></div><label for="plain">02 / IN MY OWN WORDS</label><textarea id="plain" placeholder="I think this is saying…"></textarea><button type="button" class="action" id="save">Keep this reading in this browser</button> <button type="button" class="hint" id="clear">Clear note</button><p class="status" id="saveStatus" aria-live="polite"></p></div></section><footer>Inspired by Jon’s <a href="<?= htmlspecialchars($source, ENT_QUOTES, 'UTF-8') ?>" target="_blank" rel="noopener noreferrer">“Hard sentences in ‘Introduction to Christianity’” ↗</a><br>This is a reading exercise and a tentative interpretation, not an authoritative explanation of Ratzinger’s argument.</footer></main>
<script>
const orbits=[
{label:'01 / FIRST ORBIT',heading:'Begin with an ordinary verb.',phrase:'We try to grasp an idea.',question:'What does “grasp” mean here?',choices:['To take an object with your hands.','To understand something with your own mind.','To agree with every part of it.'],correct:1,hint:'Imagine saying, “I think I get it.”',reply:'Yes. Start with our attempt to understand.'},
{label:'02 / SECOND ORBIT',heading:'Now the sentence turns around.',phrase:'Understanding goes beyond what we can simply grasp.',question:'What changes between orbit one and orbit two?',choices:['The writer is asking us to stop thinking.','The subject becomes a different book.','Knowing may involve more than our ability to take hold of an idea.'],correct:2,hint:'Pay attention to “beyond.” It does not mean “against.”',reply:'Exactly. The argument is widening the idea of understanding.'},
{label:'03 / THIRD ORBIT',heading:'A reversal of perspective.',phrase:'What if the thing we seek to know somehow holds us?',question:'Which image best fits that reversal?',choices:['A reader holding a book and finding themselves inside its story.','A reader closing a book before opening it.','A reader proving they wrote the book.'],correct:0,hint:'Who is comprehending whom now?',reply:'There it is: the knower may also be known.'},
{label:'04 / FINAL ORBIT',heading:'The knot that remains.',phrase:'If we are held inside a larger meaning, can we stand outside it and capture the whole thing?',question:'Which is the most cautious reading of the puzzle?',choices:['Everything meaningful can be measured completely.','We might receive meaning without being able to fully contain or explain it.','The sentence is telling us words have no meaning.'],correct:1,hint:'Distinguish receiving something from mastering it.',reply:'That is a possible way through the knot. It is not the last word.'}
];
const $=s=>document.querySelector(s);let step=0,solved=false,found=0;$('#stars').innerHTML=orbits.map((_,i)=>'<span class="star" id="star'+i+'"></span>').join('');
function render(){let o=orbits[step];$('#label').textContent=o.label;$('#heading').textContent=o.heading;$('#phrase').textContent=o.phrase;$('#question').textContent=o.question;$('#counter').textContent='ORBIT '+String(step+1).padStart(2,'0')+' / 04';$('#choices').replaceChildren();o.choices.forEach((c,i)=>{let b=document.createElement('button');b.type='button';b.className='option';b.textContent=c;b.addEventListener('click',()=>answer(i,b));$('#choices').append(b)});$('#hintText').textContent='';$('#feedback').textContent='';$('#next').hidden=true;solved=false}function answer(i,button){if(solved)return;const o=orbits[step];if(i!==o.correct){button.classList.add('wrong');button.disabled=true;$('#feedback').textContent='Not quite. Try another angle.';return}solved=true;button.classList.add('correct');[...$('#choices').children].forEach(b=>b.disabled=true);$('#feedback').textContent=o.reply;$('#star'+step).classList.add('lit');found++;$('#score').textContent=found+' FOUND';$('#fill').style.width=(found/4*100)+'%';$('#progress').setAttribute('aria-valuenow',found);$('#next').hidden=false;$('#next').textContent=step===3?'Explore your own sentence ↓':'Next orbit →'}$('#hint').addEventListener('click',()=>$('#hintText').textContent=orbits[step].hint);$('#next').addEventListener('click',()=>{if(step<3){step++;render()}else{$('#workbench').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'})}});render();
function split(){const val=$('#original').value.trim();const box=$('#pieces');box.replaceChildren();if(!val){$('#saveStatus').textContent='Write a sentence first.';return}const parts=val.split(/(?<=[,;:—–])\s*|(?<=\.)\s+(?=[A-Z])/u).map(x=>x.trim()).filter(Boolean);parts.forEach((part,i)=>{let s=document.createElement('span');s.className='piece';s.textContent=String(i+1).padStart(2,'0')+'  '+part;box.append(s)});$('#saveStatus').textContent=parts.length===1?'One piece so far. Look for the turn in the thought.':'Pieces are clues; you decide how they connect.'}$('#split').addEventListener('click',split);try{const saved=JSON.parse(localStorage.getItem('sentence-observatory-note')||'null');if(saved){$('#original').value=saved.original||'';$('#plain').value=saved.plain||'';if(saved.original)split()}}catch(e){}$('#save').addEventListener('click',()=>{try{localStorage.setItem('sentence-observatory-note',JSON.stringify({original:$('#original').value,plain:$('#plain').value}));$('#saveStatus').textContent='Saved on this device. Your sentence stays yours.'}catch(e){$('#saveStatus').textContent='This browser could not save the note; you can still copy it.'}});$('#clear').addEventListener('click',()=>{$('#original').value='';$('#plain').value='';$('#pieces').replaceChildren();try{localStorage.removeItem('sentence-observatory-note')}catch(e){}$('#saveStatus').textContent='Note cleared.'});
</script></body></html>
